&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot; data-markdown-start-index=&quot;574&quot;&gt;You review and record business transactions, ensuring accurate financial representation.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot; data-markdown-start-index=&quot;664&quot;&gt;You collaborate closely with auditors and tax consultants and support during audits.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot; data-markdown-start-index=&quot;750&quot;&gt;You contribute ideas for the improvement and digitalization of financial accounting processes.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot; data-markdown-start-index=&quot;846&quot;&gt;You serve as the main point of contact for all financial accounting inquiries and handle external queries regarding tax matters.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Required Skills&lt;/span&gt;&lt;/p&gt;
