&lt;ul class=&quot;pb-2 flex flex-col gap-1 list-disc pl-6 text-foreground text-base leading-relaxed&quot;&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;English:&lt;/strong&gt; Professional proficiency required&lt;/li&gt;
