&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;/p&gt;
&lt;h4&gt;&lt;span style=&quot;color: rgb(0, 4, 51); font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;&lt;span style=&quot;color: rgb(0, 222, 182);&quot;&gt;Location:&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Milton Keynes&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;office / Hybrid (2 days per week in the office)&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:80,&amp;quot;335559739&amp;quot;:40}&quot;&gt; &lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 4, 51); font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;&lt;span style=&quot;color: rgb(0, 222, 182);&quot;&gt;Reporting to:&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Head of Engineering&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:80,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;
&lt;h4&gt;&lt;span style=&quot;color: rgb(0, 222, 182); font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;The Role&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 4, 51); font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We’re&amp;nbsp;looking for an experienced Engineering Manager to lead one or more of our cross-functional product development teams at Rightmove.&amp;nbsp;You’ll&amp;nbsp;be responsible for&amp;nbsp;building a healthy, high-performing team by enabling others to do their best work,&amp;nbsp;maintaining&amp;nbsp;strong delivery focus, and fostering a culture that reflects our values.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 4, 51); font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Engineering Managers at Rightmove are not just people leaders, but delivery enablers, engineering advocates, and strategic partners to Product Managers.&amp;nbsp;You’ll&amp;nbsp;work collaboratively to ensure teams are focusing on the right things, solving valuable problems, and&amp;nbsp;operating&amp;nbsp;in a sustainable, inclusive way.&amp;nbsp;You’ll&amp;nbsp;have&amp;nbsp;a big impact&amp;nbsp;on the shape of our engineering organisation, playing a key role in how we plan, deliver, grow talent, and scale systems across the business.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 4, 51); font-size: 10pt;&quot;&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span style=&quot;color: rgb(0, 4, 51);&quot;&gt;&lt;strong&gt;A note from your future manager: &lt;/strong&gt;&lt;em&gt;By joining us, you&#39;ll lead a team building the tools our CX colleagues depend on every day, and help shape how AI and our backoffice transformation change their work. Expect honest feedback, room to grow, and a manager who&#39;ll back you all the way.&lt;/em&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h4&gt;&lt;span style=&quot;color: rgb(0, 4, 51); font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For a glimpse into the technical make-up of the UKs favourite property portal works, head to&amp;nbsp;our&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;color: rgb(0, 222, 182);&quot;&gt;&lt;a style=&quot;color: rgb(0, 222, 182);&quot; href=&quot;https://rightmove.blog/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;tech blog.&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;
