&lt;/li&gt;
&lt;li data-local-id=&quot;1e4ba525-899c-4726-bb5c-11ee6e16d481&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
