&lt;li&gt;&lt;strong&gt;Wellbeing first:&amp;nbsp;&lt;/strong&gt;Gesundheitsleistungen, attraktive Altersvorsorge sowie Mental Health Awareness Days stellen deine Gesundheit in den Mittelpunkt.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Practice makes perfect&lt;/strong&gt;: Entfalte dich mit unseren vielfältigen Weiterbildungen und nutze unsere internen Karriereprogramme für deine Entwicklung im WPP-Netzwerk.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;More than just a job&lt;/strong&gt;: Dich erwarten unvergessliche Events, Mitarbeitendenrabatte und weitere Highlights wie das Job Ticket, Wellhub oder das Job Bike.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Be yourself&lt;/strong&gt;: Bei uns ist jede:r herzlich willkommen - Vielfalt und Chancengleichheit liegen uns am Herzen.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;/p&gt;
&lt;h4&gt;&amp;nbsp;&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;Das bewegst du:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;section&gt;&lt;span class=&quot;TextRun SCXW33926073 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;Als&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW33926073 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;Senior&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;Creative Concept&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW33926073 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&amp;nbsp;(&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW33926073 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&lt;strong&gt;Mensch)&lt;/strong&gt; bist du unser kreativer Kopf&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;und übernimmst die inhaltliche Führung bei der Erstellung von&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;Konzepte&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;n&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&amp;nbsp;und Kampagnen. Dabei greifst du auf&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;d&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;ein&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;spezifisches&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&amp;nbsp;Fachwissen aus den&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;B&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;ereichen&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW33926073 BCX8&quot;&gt;Copywriting&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;, Art&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW33926073 BCX8&quot;&gt;Direction&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;&amp;nbsp;oder&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;K&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;on&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;z&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;epti&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW33926073 BCX8&quot;&gt;on zurück.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW33926073 BCX8&quot;&gt;&lt;span class=&quot;SCXW33926073 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br class=&quot;SCXW33926073 BCX8&quot;&gt;&lt;/span&gt;&lt;/section&gt;
&lt;section&gt;&lt;/section&gt;
&lt;p&gt;&lt;strong&gt;Deine Mission: Kreative Exzellenz!&lt;/strong&gt;&lt;/p&gt;
&lt;section&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Kreation&amp;nbsp;trifft&amp;nbsp;Media:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Dein Fokus liegt auf der Entwicklung und Umsetzung kanalübergreifender Konzepte und kulturell relevanter Kampagnen.&amp;nbsp;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Diese erstellst du im Kontext der Mediaagentur passgenau mit Blick auf die Mediaplanung und stehst im engen Austausch mit deinen Kolleg:innen aus der Media.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW215874325 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW215874325 BCX8&quot;&gt;Interdisziplinäre Zusammenarbeit:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW215874325 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW215874325 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW215874325 BCX8&quot;&gt;Um effizienter und nachhaltiger an Projekten zu arbeiten, stimmst du dich regelmäßig mit&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW215874325 BCX8&quot;&gt;Expert:i&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW215874325 BCX8&quot;&gt;nnen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW215874325 BCX8&quot;&gt;&amp;nbsp;aus anderen Fachabteilungen wie Brand Experience oder&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW215874325 BCX8&quot;&gt;Social&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW215874325 BCX8&quot;&gt; Media ab.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
