&lt;p&gt;&lt;strong&gt;Mission Brief&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW141803539 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;As a GNC Engineer at Isar Aerospace SE, you develop&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW141803539 BCX0&quot;&gt;the guidance&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;, navigation, and control systems that enable Spectrum to&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;operate&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;&amp;nbsp;safely, accurately, and efficiently throughout its mission. You design, verify, and&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;validate&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;&amp;nbsp;flight algorithms that&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;determine&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;&amp;nbsp;the vehicle’s position, velocity, and attitude while steering it along its&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;optimal&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;&amp;nbsp;trajectory during all phases of flight. By combining flight dynamics,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;state&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW141803539 BCX0&quot;&gt;&amp;nbsp;estimation, control theory, and high-fidelity simulation, you ensure robust performance in the presence of uncertainties and disturbances. Your work is essential to maximizing mission success, payload capability, and the reliability of every Spectrum launch.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW141803539 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Your Role in Our Space Mission:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Architect the next&amp;nbsp;generation&amp;nbsp;navigation system for&amp;nbsp;an orbital launch vehicle&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Perform Navigation algorithm tuning and improvements based on flight data&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Responsible for ground and flight integrity monitoring&amp;nbsp;for safety critical navigation systems&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ownership of all GNSS applications on the vehicle&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Perform GNSS Integrity studies&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Qualification Checklist&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;BSc/MSc/PhD in&amp;nbsp;Mechanical, Aerospace,&amp;nbsp;Electrical&amp;nbsp;or Robotics&amp;nbsp;Engineering, Physics, Mathematics or similar&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Proficient in&amp;nbsp;inertial navigation algorithms and Kalman filter techniques&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;3+ years of experience with GNSS receiver configurations and testing (GNSS simulator test setups)&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Strong understanding of integrity monitoring and jamming and spoofing&amp;nbsp;resilience&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with performing GNSS integrity studies and analysis&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience in developing with MATLAB&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience&amp;nbsp;in developing with Python and C++&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Proficient with Git&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Maintain and drive a high standard of technical documentation&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Fluent in English&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
