&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Travel&amp;nbsp;allowance:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Travel&amp;nbsp;expenses&amp;nbsp;are&amp;nbsp;fully&amp;nbsp;reimbursed.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Holidays:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; 8%&amp;nbsp;holiday&amp;nbsp;allowance&amp;nbsp;and&amp;nbsp;26&amp;nbsp;vacation&amp;nbsp;days&amp;nbsp;per&amp;nbsp;year&amp;nbsp;(plus&amp;nbsp;the&amp;nbsp;option&amp;nbsp;to&amp;nbsp;buy&amp;nbsp;9 extra&amp;nbsp;days!).&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Hybrid&amp;nbsp;Working&amp;nbsp;allowance:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; €30 net per&amp;nbsp;month&amp;nbsp;for&amp;nbsp;full-time&amp;nbsp;employees.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;&lt;strong&gt;Epassi-vergoeding&lt;/strong&gt; van&amp;nbsp;&lt;strong&gt;€10 &lt;/strong&gt;per maand die je kunt uitgeven aan persoonlijke behoeften.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bring Your Own Device (BYOD):&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; You will receive a monthly phone allowance of €57.50 net.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Lunch&amp;nbsp;facilities:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Affordable&amp;nbsp;lunch in&amp;nbsp;the&amp;nbsp;cafeteria&amp;nbsp;and&amp;nbsp;a&amp;nbsp;barista&amp;nbsp;for&amp;nbsp;the&amp;nbsp;best coffee.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Health&amp;nbsp;insurance:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Benefit&amp;nbsp;from&amp;nbsp;our&amp;nbsp;collective&amp;nbsp;health&amp;nbsp;insurance&amp;nbsp;scheme.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Events and team spirit:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Celebrate special moments with us, such as the&amp;nbsp;PlanetM&amp;nbsp;Festival, Pride Week, and the annual Christmas party.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
