&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;9&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Owning SystemVerilog RTL architecture/implementation for Artix&lt;span data-contrast=&quot;auto&quot;&gt;‑&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;7 and&amp;nbsp;Kintex&amp;nbsp;UltraScale&amp;nbsp;(SystemVerilog,&amp;nbsp;Vivado)&lt;/span&gt;&lt;/li&gt;
